1:import { appendFile, mkdir, readFile, rename, rm, writeFile } from "node:fs/promises";
2:import { randomUUID } from "node:crypto";
3:import { dirname, join } from "node:path";
4:import { maskCep, redactSensitiveText } from "./privacy.ts";
5:import type {
6:  AuditEvent,
7:  CollectedFields,
8:  CollectedValue,
9:  ConversationState,
10:} from "./types.ts";
11:
12:const identifierPattern = /^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$/u;
13:const stages = new Set(["collecting", "quoting", "resolved", "handoff"]);
14:
15:function statePath(directory: string, conversationId: string): string {
16:  if (!identifierPattern.test(conversationId)) {
17:    throw new Error("conversation_id inválido");
18:  }
19:  return join(directory, `${conversationId}.json`);
20:}
21:
22:function isRecord(value: unknown): value is Record<string, unknown> {
23:  return typeof value === "object" && value !== null && !Array.isArray(value);
24:}
25:
26:function parseState(raw: string, conversationId: string): ConversationState {
27:  const value: unknown = JSON.parse(raw);
28:  if (
29:    !isRecord(value) ||
30:    value.version !== 2 ||
31:    value.conversation_id !== conversationId ||
32:    typeof value.stage !== "string" ||
33:    !stages.has(value.stage) ||
34:    !isRecord(value.fields) ||
35:    !isRecord(value.processed_messages) ||
36:    !Array.isArray(value.quote_jobs) ||
37:    !Array.isArray(value.outbox) ||
38:    typeof value.ambiguity_count !== "number"
39:  ) {
40:    throw new Error(`Estado inválido para ${conversationId}`);
41:  }
42:  return value as unknown as ConversationState;
43:}
44:
45:function initialState(conversationId: string): ConversationState {
46:  return {
47:    version: 2,
48:    conversation_id: conversationId,
49:    stage: "collecting",
50:    fields: {},
51:    ambiguity_count: 0,
52:    processed_messages: {},
53:    active_quote_request_id: null,
54:    quote_jobs: [],
55:    outbox: [],
56:    quote: null,
57:    handoff_reason: null,
58:  };
59:}
60:
61:export class FileConversationStore {
62:  private readonly directory: string;
63:
64:  constructor(directory: string) {
65:    this.directory = directory;
66:  }
67:
68:  async load(conversationId: string): Promise<ConversationState> {
69:    const path = statePath(this.directory, conversationId);
70:    try {
71:      return parseState(await readFile(path, "utf8"), conversationId);
72:    } catch (error) {
73:      if ((error as NodeJS.ErrnoException).code !== "ENOENT") {
74:        throw error;
75:      }
76:      return initialState(conversationId);
77:    }
78:  }
79:
80:  async save(state: ConversationState): Promise<void> {
81:    const path = statePath(this.directory, state.conversation_id);
82:    await mkdir(this.directory, { recursive: true });
83:    const temporaryPath = `${path}.${randomUUID()}.tmp`;
84:    await writeFile(temporaryPath, `${JSON.stringify(state, null, 2)}\n`, {
85:      encoding: "utf8",
86:      mode: 0o600,
87:    });
88:    await rename(temporaryPath, path);
89:  }
90:
91:  async reset(conversationId: string): Promise<void> {
92:    await rm(statePath(this.directory, conversationId), { force: true });
93:  }
94:}
95:
96:export function fieldsForAudit(
97:  fields: CollectedFields,
98:): Record<string, CollectedValue<unknown>> {
99:  return Object.fromEntries(
100:    Object.entries(fields).map(([name, collected]) => [
101:      name,
102:      name === "cep"
103:        ? { ...collected, value: maskCep(String(collected.value)) }
104:        : collected,
105:    ]),
106:  );
107:}
108:
109:export class AuditLog {
110:  private readonly path: string;
111:
112:  constructor(path: string) {
113:    this.path = path;
114:  }
115:
116:  async append(event: AuditEvent): Promise<void> {
117:    await mkdir(dirname(this.path), { recursive: true });
118:    const line = redactSensitiveText(JSON.stringify(event));
119:    await appendFile(this.path, `${line}\n`, { encoding: "utf8", mode: 0o600 });
120:  }
121:}

