1:import type {
2:  CandidateFields,
3:  CollectedFields,
4:  FieldOrigin,
5:  QuotePayload,
6:  RequiredFieldName,
7:} from "./types.ts";
8:import { requiredFieldNames } from "./types.ts";
9:
10:export interface ValidatedValues {
11:  plano?: string;
12:  idade?: number;
13:  veiculo_ano?: number;
14:  cep?: string;
15:  data_inicio?: string;
16:}
17:
18:export interface ValidationResult {
19:  values: ValidatedValues;
20:  errors: string[];
21:}
22:
23:function normalizePlan(value: unknown): string | null {
24:  if (typeof value !== "string") {
25:    return null;
26:  }
27:  const plan = value.normalize("NFD").replace(/\p{Diacritic}/gu, "").trim().toLowerCase();
28:  return ["essencial", "completo", "premium"].includes(plan) ? plan : null;
29:}
30:
31:function normalizeInteger(value: unknown, minimum: number, maximum: number): number | null {
32:  if (typeof value !== "number" && (typeof value !== "string" || !/^\d+$/u.test(value.trim()))) {
33:    return null;
34:  }
35:  const parsed = Number(value);
36:  return Number.isInteger(parsed) && parsed >= minimum && parsed <= maximum ? parsed : null;
37:}
38:
39:function normalizeCep(value: unknown): string | null {
40:  if (typeof value !== "string" && typeof value !== "number") {
41:    return null;
42:  }
43:  const digits = String(value).replace(/\D/gu, "");
44:  return digits.length === 8 ? `${digits.slice(0, 5)}-${digits.slice(5)}` : null;
45:}
46:
47:function normalizeDate(value: unknown): string | null {
48:  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/u.test(value)) {
49:    return null;
50:  }
51:  const [year, month, day] = value.split("-").map(Number);
52:  if (year === undefined || month === undefined || day === undefined) {
53:    return null;
54:  }
55:  const date = new Date(Date.UTC(year, month - 1, day));
56:  return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day
57:    ? value
58:    : null;
59:}
60:
61:function assignIfPresent<T>(
62:  candidate: unknown,
63:  normalized: T | null,
64:  name: RequiredFieldName,
65:  label: string,
66:  values: ValidatedValues,
67:  errors: string[],
68:): void {
69:  if (candidate === undefined || candidate === null) {
70:    return;
71:  }
72:  if (normalized === null) {
73:    errors.push(`${label} inválido`);
74:    return;
75:  }
76:  Object.assign(values, { [name]: normalized });
77:}
78:
79:export function validateCandidates(candidates: CandidateFields): ValidationResult {
80:  const values: ValidatedValues = {};
81:  const errors: string[] = [];
82:  assignIfPresent(candidates.plano, normalizePlan(candidates.plano), "plano", "plano", values, errors);
83:  assignIfPresent(candidates.idade, normalizeInteger(candidates.idade, 0, 200), "idade", "idade", values, errors);
84:  assignIfPresent(
85:    candidates.veiculo_ano,
86:    normalizeInteger(candidates.veiculo_ano, 1950, 2100),
87:    "veiculo_ano",
88:    "ano do veículo",
89:    values,
90:    errors,
91:  );
92:  assignIfPresent(candidates.cep, normalizeCep(candidates.cep), "cep", "CEP", values, errors);
93:  assignIfPresent(
94:    candidates.data_inicio,
95:    normalizeDate(candidates.data_inicio),
96:    "data_inicio",
97:    "data de início",
98:    values,
99:    errors,
100:  );
101:  return { values, errors };
102:}
103:
104:export function mergeFields(
105:  fields: CollectedFields,
106:  values: ValidatedValues,
107:  messageId: string,
108:  source: FieldOrigin["source"] = "llm",
109:): CollectedFields {
110:  const merged = { ...fields };
111:  for (const [name, value] of Object.entries(values)) {
112:    Object.assign(merged, {
113:      [name]: { value, origin: { message_id: messageId, source } },
114:    });
115:  }
116:  return merged;
117:}
118:
119:export function hasFieldChanges(fields: CollectedFields, values: ValidatedValues): boolean {
120:  return Object.entries(values).some(([name, value]) => {
121:    const current = fields[name as RequiredFieldName];
122:    return current === undefined || current.value !== value;
123:  });
124:}
125:
126:export function missingFields(fields: CollectedFields): RequiredFieldName[] {
127:  return requiredFieldNames.filter((name) => fields[name] === undefined);
128:}
129:
130:export function toQuotePayload(fields: CollectedFields): QuotePayload {
131:  if (!fields.plano || !fields.idade || !fields.veiculo_ano || !fields.cep || !fields.data_inicio) {
132:    throw new Error("Campos obrigatórios incompletos");
133:  }
134:  return {
135:    plano_id: fields.plano.value,
136:    idade: fields.idade.value,
137:    veiculo_ano: fields.veiculo_ano.value,
138:    cep: fields.cep.value,
139:    data_inicio: fields.data_inicio.value,
140:  };
141:}

[src/privacy.ts#<file-tag-redacted>]
1:const emailPattern = /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/giu;
2:const cpfPattern = /(?<![A-Za-z0-9-])\d{3}[.\s]?\d{3}[.\s]?\d{3}[-\s]?\d{2}(?![A-Za-z0-9-])/gu;
3:const phonePattern = /(?<![A-Za-z0-9-])(?:\+?55[\s.-]*)?(?:\(\d{2}\)|\d{2})[\s.-]*9?\d{4}[\s.-]*\d{4}(?![A-Za-z0-9-])/gu;
4:
5:export function redactSensitiveText(value: string): string {
6:  return value
7:    .replace(emailPattern, "<email_redacted>")
8:    .replace(cpfPattern, "<cpf_redacted>")
9:    .replace(phonePattern, "<phone_redacted>");
10:}
11:
12:export function maskCep(value: string): string {
13:  const digits = value.replace(/\D/gu, "");
14:  return digits.length === 8 ? `${digits.slice(0, 2)}***-***` : "<cep_invalid>";
15:}

