1:import { randomUUID } from "node:crypto";
2:import { readFile } from "node:fs/promises";
3:import { stdin, stdout } from "node:process";
4:import { createInterface } from "node:readline/promises";
5:import { parseArgs } from "node:util";
6:import { AutoSeguroAgent } from "./agent.ts";
7:import { OpenAICompatibleLlm } from "./llm.ts";
8:import { AuditLog, FileConversationStore } from "./persistence.ts";
9:import { redactSensitiveText } from "./privacy.ts";
10:import { QuoteClient } from "./quote-client.ts";
11:import type { IncomingMessage, MessageType, OutboxMessage } from "./types.ts";
12:
13:interface ReplayRecord {
14:  conversation_id?: unknown;
15:  message_id?: unknown;
16:  message_index?: unknown;
17:  sender_role?: unknown;
18:  message_type?: unknown;
19:  message_body?: unknown;
20:  text?: unknown;
21:}
22:
23:const messageTypes = new Set<MessageType>(["text", "audio", "image", "document"]);
24:
25:function readReplayRecord(line: string, fallbackConversationId: string, index: number): IncomingMessage | null {
26:  const record = JSON.parse(line) as ReplayRecord;
27:  if (record.sender_role !== undefined && record.sender_role !== "lead") {
28:    return null;
29:  }
30:  const conversationId = typeof record.conversation_id === "string"
31:    ? record.conversation_id
32:    : fallbackConversationId;
33:  const text = typeof record.text === "string" ? record.text : record.message_body;
34:  const rawType = typeof record.message_type === "string" ? record.message_type : "text";
35:  if (typeof text !== "string" || !messageTypes.has(rawType as MessageType)) {
36:    throw new Error(`Linha ${index + 1} do replay é inválida`);
37:  }
38:  const sourceIndex = typeof record.message_index === "number" ? record.message_index : index;
39:  const messageId = typeof record.message_id === "string"
40:    ? record.message_id
41:    : `${conversationId}-${sourceIndex}`;
42:  return {
43:    conversation_id: conversationId,
44:    message_id: messageId,
45:    message_type: rawType as MessageType,
46:    text,
47:  };
48:}
49:
50:function printAsyncReply(message: OutboxMessage): void {
51:  console.log(`AutoSeguro [assíncrono]: ${message.text}`);
52:}
53:
54:async function emitReady(agent: AutoSeguroAgent, conversationId: string): Promise<void> {
55:  await agent.waitForIdle(conversationId);
56:  await agent.deliverOutbox(conversationId, printAsyncReply);
57:}
58:
59:function watchOutbox(agent: AutoSeguroAgent, conversationId: string): void {
60:  void emitReady(agent, conversationId).catch((error: unknown) => {
61:    const message = error instanceof Error ? error.message : String(error);
62:    console.error(`Erro assíncrono: ${redactSensitiveText(message)}`);
63:  });
64:}
65:
66:async function prepareConversation(agent: AutoSeguroAgent, conversationId: string): Promise<void> {
67:  await agent.deliverOutbox(conversationId, printAsyncReply);
68:  if (await agent.resume(conversationId)) {
69:    watchOutbox(agent, conversationId);
70:  }
71:}
72:
73:async function replay(path: string, conversationId: string, agent: AutoSeguroAgent): Promise<void> {
74:  const lines = (await readFile(path, "utf8")).split(/\r?\n/u).filter((line) => line.trim() !== "");
75:  for (const [index, line] of lines.entries()) {
76:    const message = readReplayRecord(line, conversationId, index);
77:    if (!message) {
78:      continue;
79:    }
80:    console.log(`Lead: ${redactSensitiveText(message.text)}`);
81:    const reply = await agent.handle(message);
82:    console.log(`AutoSeguro: ${reply.text}`);
83:  }
84:  await emitReady(agent, conversationId);
85:}
86:
87:async function interactive(conversationId: string, agent: AutoSeguroAgent): Promise<void> {
88:  const terminal = createInterface({ input: stdin, output: stdout });
89:  console.log(`AutoSeguro: Olá. Envie "sair" para encerrar. Conversa ${conversationId}.`);
90:  try {
91:    while (true) {
92:      const text = await terminal.question("Você: ");
93:      if (text.trim().toLowerCase() === "sair") {
94:        await emitReady(agent, conversationId);
95:        return;
96:      }
97:      const reply = await agent.handle({
98:        conversation_id: conversationId,
99:        message_id: `${conversationId}-${randomUUID()}`,
100:        message_type: "text",
101:        text,
102:      });
103:      console.log(`AutoSeguro: ${reply.text}`);
104:      watchOutbox(agent, conversationId);
105:    }
106:  } finally {
107:    terminal.close();
108:  }
109:}
110:
111:async function main(): Promise<void> {
112:  const { values } = parseArgs({
113:    options: {
114:      conversation: { type: "string", short: "c" },
115:      replay: { type: "string", short: "r" },
116:      reset: { type: "boolean", default: false },
117:      help: { type: "boolean", short: "h", default: false },
118:    },
119:  });
120:  if (values.help) {
121:    console.log("npm run chat -- [--conversation ID] [--replay arquivo.jsonl] [--reset]");
122:    return;
123:  }
124:  const conversationId = values.conversation ?? `cli-${randomUUID()}`;
125:  const store = new FileConversationStore(process.env.STATE_DIR ?? ".runtime/conversations");
126:  if (values.reset) {
127:    await store.reset(conversationId);
128:  }
129:  const agent = new AutoSeguroAgent(
130:    store,
131:    new AuditLog(process.env.AUDIT_LOG_PATH ?? ".runtime/audit.jsonl"),
132:    OpenAICompatibleLlm.fromEnv(),
133:    new QuoteClient({
134:      baseUrl: process.env.QUOTE_API_URL ?? "http://127.0.0.1:8000",
135:      timeoutMs: Number(process.env.QUOTE_TIMEOUT_MS ?? "3000"),
136:      maxAttempts: Number(process.env.QUOTE_MAX_ATTEMPTS ?? "3"),
137:    }),
138:  );
139:  await prepareConversation(agent, conversationId);
140:  if (values.replay) {
141:    await replay(values.replay, conversationId, agent);
142:    return;
143:  }
144:  await interactive(conversationId, agent);
145:}
146:
147:main().catch((error: unknown) => {
148:  const message = error instanceof Error ? error.message : String(error);
149:  console.error(`Erro: ${redactSensitiveText(message)}`);
150:  process.exitCode = 1;
151:});

